mapper.select:
select

from sys_audit_event a
left join sys_user u on a.operator_id = u.id


    and (
        cast(a.operator_id as char) like concat('%', #{operatorKeyword}, '%')
        or u.username like concat('%', #{operatorKeyword}, '%')
    )


    and a.event_type = #{eventType}


    and a.resource_type = #{resourceType}


    and a.result = #{result}


order by a.occurred_at desc, a.id desc
limit #{pageSize} offset #{offset}

select count(1)
from sys_audit_event a
left join sys_user u on a.operator_id = u.id


    and (
        cast(a.operator_id as char) like concat('%', #{operatorKeyword}, '%')
        or u.username like concat('%', #{operatorKeyword}, '%')
    )


    and a.event_type = #{eventType}


    and a.resource_type = #{resourceType}


    and a.result = #{result}
